/* HEXA BATTLEGROUNDS setup — PART 19 OF 20. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('final_code-grid-1003', 'grid', 'final_code', 'The Final Code', 'observation', 2, array['finale']::text[], 'Squad 00''s master vault. Read the final code from the grid. This is worth the most points of the night.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5 6\n1 | Y S O O M K\n2 | L I E E G Z\n3 | A O K S O H\n4 | L F P S E C\n5 | X W X C L E\n6 | A W H I R S","mono":true},"decoder":{"title":"Marked coordinates","body":"(3, 6)  (5, 4)  (1, 5)  (1, 6)  (2, 6)  (1, 3)  (5, 6)  (3, 2)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["HEXAWARE"]}]'::jsonb, false, 4, 240, 'The code is a 8-letter word ending in E.', 'Reading (column,row) gives HEXAWARE; reading it as (row,column) gives nonsense (HCMKZOEO).', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); alter table events add column if not exists is_trial boolean not null default false; alter table arenas add column if not exists match_phase int not null default 0; alter table arenas add column if not exists phase_started_at timestamptz; alter table arenas add column if not exists phase_next_at timestamptz; alter table arenas add column if not exists zone_hold boolean not null default false; create or replace function _defaults() returns jsonb language sql immutable as $$ select jsonb_build_object( 'pts_standard', 100, 'pts_hard', 150, 'pts_battle', 125, 'pts_airdrop', 75, 'pts_relay_bonus', 25, 'pts_relocation', 40, 'pen_recovery', 40, 'finale_max', 300, 'finale_entry_max', 200, 'finale_exchange_max', 200, 'hp_max', 100, 'hp_respawn', 50, 'dmg_fail', 10, 'dmg_zone', 15, 'shield_max', 60, 'shuttle_seconds', 10, 'roles_seconds', 15, 'bus_size', 3, 'arena_size', 15, 'attack_cooldown', 90, 'protect_seconds', 120, 'recovery_seconds', 120, 'zone_warning', 60, 'airdrop_window', 180, 'airdrop_interval', 0, 'intel_fallback', 90, 'relay_chance', 20, 'hint_cost', 15, 'alliance_minutes', 10, 'alliance_cost', 10, 'chat_limit', 6, 'drop_seconds', 8, 'visit_missions', 2, 'zone_auto', 0, 'zone_schedule', '20,40,55,70,85', 'sync_seconds', 0, 'auto_pacing', 0, 'phase_schedule', '2,12,30,50', 'duel_phase', 2, 'mission_time_pct', 100, 'pin_length', 6 ) $$; create or replace function _phase_zone_target(p_phase int) returns int language sql immutable as $$ select (array[0, 0, 1, 3, 4, 5])[least(5, greatest(0, p_phase)) + 1] $$; create or replace function _new_pin(p_len int) returns text language plpgsql volatile as $$ declare v text := ''; begin p_len := least(8, greatest(4, coalesce(p_len, 6))); while length(v) < p_len loop v := v || ((('x' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12))::bit(48)::bigint) % 10)::text; end loop; return v; end $$; create or replace function _weak_pin(p text) returns boolean language sql immutable as $$ select p !~ '^[0-9]{4,8}$' or p ~ '^(.)\1+$' or position(p in '01234567890') > 0 or position(p in '98765432109') > 0 $$; create or replace function _set_match_phase(p_arena uuid, p_phase int) returns void language plpgsql as $$ declare a arenas; e events; v_next timestamptz; v_sched text[]; v_min int; begin select * into a from arenas where id = p_arena for update; select * into e from events where id = a.event_id; p_phase := greatest(0, least(5, p_phase)); if p_phase < 4 and _cfg(a.event_id, 'auto_pacing') = 1 and a.play_started_at is not null then v_sched := string_to_array(_cfg_text(a.event_id, 'phase_schedule'), ','); begin v_min := nullif(trim(v_sched[p_phase + 1]), '')::int; exception when others then v_min := null; end; if v_min is not null then v_next := greatest(now() + interval '5 seconds', a.play_started_at + make_interval(mins => v_min)); end if; end if; update arenas set match_phase = p_phase, phase_started_at = now(), phase_next_at = v_next, zone_hold = false, overlay = overlay || jsonb_build_object('match', jsonb_build_object( 'phase', p_phase, 'started_at', now(), 'next_at', v_next, 'duel_phase', _cfg(a.event_id, 'duel_phase'), 'zone_target', _phase_zone_target(p_phase)), 'trial', e.is_trial) where id = p_arena; if a.match_phase is distinct from p_phase or a.phase_started_at is null then perform _feed(p_arena, 'phase.started', jsonb_build_object('phase', p_phase)); end if; perform _ping_arena(p_arena, 'phase'); end $$; create or replace function _battles_phase_guard() returns trigger language plpgsql as $$ declare a arenas; begin select * into a from arenas where id = new.arena_id; if a.match_phase < _cfg(a.event_id, 'duel_phase') then raise exception 'DUELS_LOCKED'; end if; return new; end $$; drop trigger if exists battles_phase_guard on battles; create trigger battles_phase_guard before insert on battles for each row execute function _battles_phase_guard(); create or replace function _teams_defaults() returns trigger language plpgsql as $$ declare v_n int; begin if new.name is null or new.name = '' or new.name = 'Squad ' || new.number then new.name := (array['Alpha','Bravo','Charlie','Delta','Echo','Foxtrot','Golf','Hotel','India','Juliet','Kilo','Lima', 'Mike','November','Oscar','Papa','Quebec','Romeo','Sierra','Tango','Uniform','Victor','Whiskey','Xray','Yankee','Zulu']) [1 + (new.number - 1) % 26] || '-' || lpad(new.number::text, 2, '0'); end if; if new.bus is null then select count(*) into v_n from teams where arena_id = new.arena_id; new.bus := 1 + v_n / greatest(1, _cfg(new.event_id, 'bus_size')); end if; return new; end $$; drop trigger if exists teams_defaults on teams; create trigger teams_defaults before insert on teams for each row execute function _teams_defaults(); create or replace function _pick_template(p_team uuid, p_kind text, p_tags text[]) returns text language plpgsql stable as $$ declare t teams; v_seed int; v text; v_phase int; begin select * into t from teams where id = p_team; select mission_seed into v_seed from events where id = t.event_id; select match_phase into v_phase from arenas where id = t.arena_id; select mt.id into v from mission_templates mt where mt.kind = p_kind and mt.status = 'published' and not exists (select 1 from mission_instances mi where mi.team_id = p_team and mi.template_id = mt.id) order by (mt.tags && coalesce(p_tags, '{}')) desc, (case when coalesce(v_phase, 0) <= 1 then mt.difficulty <= 1 when v_phase >= 3 then mt.difficulty >= 2 else true end) desc, md5(v_seed::text || p_team::text || mt.id || t.mission_counter::text) limit 1; if v is null then select mt.id into v from mission_templates mt where mt.kind = p_kind and mt.status = 'published' order by (mt.tags && coalesce(p_tags, '{}')) desc, md5(v_seed::text || p_team::text || mt.id || t.mission_counter::text) limit 1; end if; return v; end $$; create or replace function _start_instance( p_team uuid, p_template text, p_location text default null, p_battle uuid default null, p_airdrop uuid default null, p_sync uuid default null, p_deadline timestamptz default null, p_partner uuid default null ) returns uuid language plpgsql as $$ declare t teams; mt mission_templates; v_id uuid; v_partner uuid; v_key text; v_seed int; v_pct int; begin select * into t from teams where id = p_team for update; select * into mt from mission_templates where id = p_template; if mt.id is null then raise exception 'NO_TEMPLATE'; end if; select mission_seed into v_seed from events where id = t.event_id; v_pct := greatest(20, least(300, _cfg(t.event_id, 'mission_time_pct'))); if mt.relay then v_partner := p_partner; if v_partner is null then select x.id into v_partner from teams x where x.arena_id = t.arena_id and x.ready and x.id <> t.id order by md5(v_seed::text || t.id::text || x.id::text || t.mission_counter::text) limit 1; end if; v_key := _codeword(v_seed::text || t.id::text || t.mission_counter::text); end if; insert into mission_instances(arena_id, team_id, template_id, template_version, kind, location_id, battle_id, airdrop_id, sync_round_id, attempts_left, deadline, partner_team_id, relay_key, fallback_at) values (t.arena_id, t.id, mt.id, mt.version, mt.kind, coalesce(p_location, t.location_id), p_battle, p_airdrop, p_sync, mt.attempts, coalesce(p_deadline, now() + _secs(mt.time_limit * v_pct / 100.0)), v_partner, v_key, case when mt.relay and v_partner is not null then now() + _secs(_cfg(t.event_id, 'intel_fallback')) when mt.relay then now() end) returning id into v_id; update teams set mission_counter = mission_counter + 1, visit_missions = visit_missions + case when mt.kind in ('mission', 'relay') then 1 else 0 end where id = t.id; perform _ping_team(t.id, 'mission'); if v_partner is not null then perform _ping_team(v_partner, 'intel'); end if; return v_id; end $$; create or replace function _shift_arena(p_arena uuid, p_delta interval) returns void language plpgsql as $$ begin update arenas set shuttle_departed_at = shuttle_departed_at + p_delta, shuttle_arrive_at = shuttle_arrive_at + p_delta, roles_deadline = roles_deadline + p_delta, play_started_at = play_started_at + p_delta, zone_next_at = zone_next_at + p_delta, last_airdrop_at = last_airdrop_at + p_delta, phase_started_at = phase_started_at + p_delta, phase_next_at = phase_next_at + p_delta, overlay = case when overlay ? 'match' then jsonb_set(overlay, '{match,next_at}', coalesce(to_jsonb((overlay #>> '{match,next_at}')::timestamptz + p_delta), 'null'::jsonb)) else overlay end where id = p_arena; update mission_instances set deadline = deadline + p_delta, fallback_at = fallback_at + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update battles set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update sync_rounds set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update airdrops set expires_at = expires_at + p_delta, spawned_at = spawned_at + p_delta where arena_id = p_arena and status = 'open'; update alliances set expires_at = expires_at + p_delta, created_at = created_at + p_delta where arena_id = p_arena and status in ('proposed', 'active'); update story_events set expires_at = expires_at + p_delta where arena_id = p_arena and expires_at > now(); update teams set travel_started_at = travel_started_at + p_delta, travel_arrive_at = travel_arrive_at + p_delta, recovery_deadline = recovery_deadline + p_delta, attack_cooldown_until = attack_cooldown_until + p_delta, protected_until = protected_until + p_delta, jammed_until = jammed_until + p_delta, scan_until = scan_until + p_delta where arena_id = p_arena; end $$; create or replace function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare a arenas; r record; v_changed boolean := false; v_sched text[]; v_next int; v_at timestamptz; v_target int; begin if not pg_try_advisory_xact_lock(hashtext('tick' || p_arena::text)) then return false; end if; select * into a from arenas where id = p_arena; if a.id is null or a.paused then return false; end if; if not p_force and a.last_tick_at is not null and a.last_tick_at > now() - interval '800 milliseconds' then return false; end if; update arenas set last_tick_at = now() where id = p_arena; if a.phase = 'shuttle' and now() >= a.shuttle_arrive_at then update arenas set phase = 'roles', roles_deadline = now() + _secs(_cfg(a.event_id, 'roles_seconds')) where id = p_arena; update teams set location_id = 'gate_1', state = 'idle' where arena_id = p_arena and ready; perform _feed(p_arena, 'shuttle.arrived', '{}'::jsonb); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'roles' and now() >= a.roles_deadline then perform _finalize_roles(p_arena); update arenas set phase = 'play', play_started_at = now() where id = p_arena; perform _feed(p_arena, 'role.assignment.completed', '{}'::jsonb); perform _feed(p_arena, 'map.revealed', '{}'::jsonb); perform _set_match_phase(p_arena, 0); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase not in ('play', 'finale') then if v_changed then perform _ping_arena(p_arena, 'phase'); end if; return v_changed; end if; for r in select id from teams where arena_id = p_arena and state = 'traveling' and travel_arrive_at <= now() loop perform _arrive(r.id); v_changed := true; end loop; for r in select id from battles where arena_id = p_arena and status = 'active' and deadline <= now() loop perform _resolve_battle(r.id, null); v_changed := true; end loop; for r in select id, kind, sync_round_id from mission_instances where arena_id = p_arena and status = 'active' and deadline <= now() and kind <> 'battle' loop perform _fail(r.id, 'expired'); v_changed := true; end loop; for r in select id from teams where arena_id = p_arena and state = 'recovery' and recovery_deadline <= now() loop perform _respawn(r.id, 'timeout'); v_changed := true; end loop; for r in select id from sync_rounds where arena_id = p_arena and status = 'active' and deadline <= now() loop update sync_rounds set status = 'closed' where id = r.id; update arenas set sync_round_id = null where id = p_arena and sync_round_id = r.id; perform _feed(p_arena, 'sync.closed', '{}'::jsonb); v_changed := true; end loop; select * into a from arenas where id = p_arena; if a.phase = 'play' and a.match_phase < 4 and a.phase_next_at is not null and now() >= a.phase_next_at then perform _set_match_phase(p_arena, a.match_phase + 1); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' and not a.zone_hold and a.zone_next_at is null and a.zone_stage < 5 then v_target := _phase_zone_target(a.match_phase); if a.zone_stage < v_target then update arenas set zone_next_at = now() + _secs(_cfg(a.event_id, 'zone_warning')) where id = p_arena; perform _feed(p_arena, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); v_changed := true; end if; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' and _cfg(a.event_id, 'zone_auto') = 1 and a.zone_next_at is null and a.zone_stage < 5 and not a.zone_hold then v_sched := string_to_array(_cfg_text(a.event_id, 'zone_schedule'), ','); v_next := trim(v_sched[a.zone_stage + 1])::int; if v_next is not null then v_at := a.play_started_at + make_interval(mins => v_next); if now() >= v_at - _secs(_cfg(a.event_id, 'zone_warning')) then update arenas set zone_next_at = greatest(v_at, now() + interval '10 seconds') where id = p_arena; perform _feed(p_arena, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); v_changed := true; end if; end if; end if; select * into a from arenas where id = p_arena; if a.zone_next_at is not null and now() >= a.zone_next_at then perform _zone_advance(p_arena); v_changed := true; end if; if a.phase = 'play' and _cfg(a.event_id, 'airdrop_interval') > 0 and coalesce(a.last_airdrop_at, a.play_started_at) < now() - make_interval(mins => _cfg(a.event_id, 'airdrop_interval')) then perform _spawn_airdrop(p_arena, null, (array['common', 'common', 'rare', 'mystery', 'intel', 'cursed', 'legendary'])[1 + floor(random() * 7)::int]); v_changed := true; end if; update airdrops set status = 'expired' where arena_id = p_arena and status = 'open' and expires_at <= now(); if found then v_changed := true; end if; update mission_instances mi set status = 'cancelled' from airdrops ad where mi.airdrop_id = ad.id and ad.status = 'expired' and mi.status = 'active'; update alliances set status = 'expired' where arena_id = p_arena and status = 'proposed' and created_at < now() - interval '2 minutes'; update alliances set status = 'ended' where arena_id = p_arena and status = 'active' and expires_at <= now(); if v_changed then perform _ping_arena(p_arena, 'tick'); end if; return v_changed; end $$;
